CREATE TABLE public.tattoo_profiles (user_id uuid PRIMARY KEY, preferences jsonb NOT NULL DEFAULT '{}'::jsonb, body_photo_consent boolean NOT NULL DEFAULT false, consent_version text NOT NULL DEFAULT 'tattoo-v1', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tattoo_profiles TO authenticated;
GRANT ALL ON public.tattoo_profiles TO service_role;
ALTER TABLE public.tattoo_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "owner all" ON public.tattoo_profiles FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.tattoo_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL DEFAULT 'Minha tatuagem', intention jsonb NOT NULL DEFAULT '{}'::jsonb, checkpoints jsonb NOT NULL DEFAULT '{}'::jsonb, selected_level text NOT NULL DEFAULT 'safe', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tattoo_projects TO authenticated;
GRANT ALL ON public.tattoo_projects TO service_role;
ALTER TABLE public.tattoo_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY "owner all" ON public.tattoo_projects FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.tattoo_care_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, project_id uuid NOT NULL REFERENCES public.tattoo_projects(id) ON DELETE CASCADE, observed_at date NOT NULL DEFAULT CURRENT_DATE, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tattoo_care_logs TO authenticated;
GRANT ALL ON public.tattoo_care_logs TO service_role;
ALTER TABLE public.tattoo_care_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "owner all" ON public.tattoo_care_logs FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.tattoo_projects p WHERE p.id=project_id AND p.user_id=auth.uid()));
ALTER TABLE public.photos ADD COLUMN tattoo_project_id uuid REFERENCES public.tattoo_projects(id) ON DELETE CASCADE;
ALTER TABLE public.reminders ADD COLUMN tattoo_project_id uuid REFERENCES public.tattoo_projects(id) ON DELETE CASCADE;
ALTER TABLE public.safety_config ADD COLUMN tattoo_disclaimer text NOT NULL DEFAULT 'Tatuagens são permanentes. Valide escrita, símbolos, referências culturais, região e riscos de pele com profissionais qualificados. Este planejamento não substitui avaliação profissional.';
CREATE OR REPLACE FUNCTION public.validate_tattoo_photo() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.kind IN ('tattoo_body','tattoo_reference') THEN IF NEW.tattoo_project_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.tattoo_projects WHERE id=NEW.tattoo_project_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'Projeto inválido'; END IF; IF NOT EXISTS (SELECT 1 FROM public.consents WHERE user_id=NEW.user_id AND photo_processing) THEN RAISE EXCEPTION 'Permissão de fotos necessária'; END IF; IF NEW.kind='tattoo_body' AND NOT EXISTS (SELECT 1 FROM public.tattoo_profiles WHERE user_id=NEW.user_id AND body_photo_consent) THEN RAISE EXCEPTION 'Consentimento corporal necessário'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_tattoo_photo BEFORE INSERT OR UPDATE ON public.photos FOR EACH ROW EXECUTE FUNCTION public.validate_tattoo_photo();
CREATE POLICY "tattoo body upload consent" ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (bucket_id <> 'user-photos' OR name NOT LIKE '%/tattoo-body-%' OR (EXISTS (SELECT 1 FROM public.tattoo_profiles WHERE user_id=auth.uid() AND body_photo_consent) AND EXISTS (SELECT 1 FROM public.consents WHERE user_id=auth.uid() AND photo_processing)));
CREATE INDEX tattoo_projects_user_idx ON public.tattoo_projects(user_id);
CREATE INDEX tattoo_care_project_idx ON public.tattoo_care_logs(project_id);